\begin{theorem}\label{theorem1}
For nonnegative integers $k,m$ with $k+m\leq N$, define $\theta_{k,m}=\frac{2k+m}{N}$ and 
\begin{align*}
p_{k,m}(x)=2^{-m}\binom{m}{x-k},
\quad x=0,\ldots,N,
\end{align*}
where $\binom{m}{j}=0$ when $j\notin\{0,\ldots,m\}$. Let $\cK_N$ be the set of all such $(k,m)$ and define
\begin{align}\label{eq:problem}
\kappa_N
=
\min_{d=(d_0,\ldots,d_N)\in[0,2]^{N+1}}
\max_{(k,m)\in\cK_N}
\sum_{x=0}^N
p_{k,m}(x)(d_x-\theta_{k,m})^2.
\end{align}
Then, over all measurable estimators,
\begin{align*}
\inf _{(\delta,\hat\beta)}\sup_{Y(\cdot)\in [L,U]^{2N}}\E_\delta \left[(\hat\beta - \beta)^2\right] =  (U-L)^2 \kappa_N.
\end{align*}
A minimax procedure is independent random assignment, with the estimator
\begin{align*}
\hat\beta^*_{NL} = \hat\beta^* + (U-L)\sum_{x=0}^N\left(d_x^*-\frac{2x}{N}\right)p_x(Z)
\end{align*}
where $\hat\beta^*$ is the optimal affine estimator in Proposition \ref{prop1},  $d^*=(d_0^*,\dots,d_N^*)$ is any solution to \eqref{eq:problem}, $p_x(z)=Pr(\sum_i B_i=x)$ for $B_i\stackrel{ind}{\sim}Bernoulli(z_i)$, and $Z=(Z_i)_{i=1}^N$ for
\begin{align*}
Z_i=\frac{1}{2}+\frac{(2D_i - 1)(Y_i-\frac{U+L}{2})}{U-L}\in[0,1].
\end{align*}
\end{theorem}
\noindent\emph{Step 3: Attainment.}
For $d\in[0,2]^{N+1}$ define 
\[
\mathcal B_d(z)=\sum_{x=0}^Nd_xp_x(z),
\]
where $p_x(z)$ is the probability that a sum of independent Bernoulli$(z_i)$ variables equals $x$.  The function $\mathcal B_d$ is affine in each coordinate separately and equals $d_{\sum_i z_i}$ at every $z\in\{0,1\}^N$.

Under independent randomization, the normalized risk at $(A,C)\in[0,1]^{2N}$ is
\[
R_d(A,C)=2^{-N}\sum_{g\in\{0,1\}^N}
\left[\mathcal B_d\{Z_g(A,C)\}-\frac1N\sum_i(A_i+C_i)\right]^2.
\]
Fix all coordinates except $A_i$.  In terms with $g_i=1$, both the estimate and the target are affine in $A_i$; in terms with $g_i=0$, the estimate is constant and the target is affine.  Each squared difference is therefore convex in $A_i$.  The same argument applies separately to every $A_i$ and $C_i$.  Thus $R_d$ is separately convex on the cube, and successively maximizing over coordinates shows that its maximum is attained at a vertex.  Taking $d=d^*$ solving \eqref{eq:problem}, every vertex risk is at most $\kappa_N$ by construction, so
\[
\sup_{(A,C)\in[0,1]^{2N}}R_{d^*}(A,C)\leq\kappa_N.
\]
Along with Step 2, this shows the normalized minimax value of $\kappa_N$ and hence the stated value $\Delta^2\kappa_N$. Finally, note that
\[
\sum_{x=0}^N xp_x(Z)=\sum_{i=1}^NZ_i,
\hspace{0.3cm}\text{ and }\hspace{0.3cm}
\widehat\beta^*=\Delta\left(\frac2N\sum_iZ_i-1\right).
\]
Therefore we can write:
\[
\hat\beta^*_{NL}=\Delta\{\mathcal B_{d^*}(Z)-1\}
=\widehat\beta^*+\Delta\sum_{x=0}^N\left(d_x^*-\frac{2x}{N}\right)p_x(Z).
\]
